        /// The name on the byline, when it is not the writer's own.
        public var penName: String?
        /// The snapshot the writer wants to find without looking — what they last
        /// sent out.
        public var pinnedVersionId: String?
        /// Short form for a running header; a long title wraps and ruins it.
        public var shortTitle: String?
        public var status: WorkStatus
        public var subtitle: String?
        public var synopsis: String?
        /// The day they mean to get there by, `YYYY-MM-DD`.
        public var targetDate: String?
        /// How long the book is meant to be, when the writer has said.
        public var targetWords: Int?
        public var templateId: String?
        public var title: String
        public var updatedAt: String
        public var wordCount: Int

        public init(
            copyrightLine: String? = nil,
            createdAt: String,
            currentVersionId: String? = nil,
            dedication: String? = nil,
            epigraph: String? = nil,
            epigraphSource: String? = nil,
            genre: Genre? = nil,
            id: String,
            kind: WorkKind,
            ownerId: String,
            penName: String? = nil,
            pinnedVersionId: String? = nil,
            shortTitle: String? = nil,
            status: WorkStatus,
            subtitle: String? = nil,
            synopsis: String? = nil,
            targetDate: String? = nil,
            targetWords: Int? = nil,
            templateId: String? = nil,
            title: String,
            updatedAt: String,
            wordCount: Int
        ) {
            self.copyrightLine = copyrightLine
            self.createdAt = createdAt
            self.currentVersionId = currentVersionId
            self.dedication = dedication
            self.epigraph = epigraph
            self.epigraphSource = epigraphSource
            self.genre = genre
            self.id = id
            self.kind = kind
            self.ownerId = ownerId
            self.penName = penName
            self.pinnedVersionId = pinnedVersionId
            self.shortTitle = shortTitle
            self.status = status
            self.subtitle = subtitle
            self.synopsis = synopsis
            self.targetDate = targetDate
            self.targetWords = targetWords
            self.templateId = templateId
            self.title = title
            self.updatedAt = updatedAt
            self.wordCount = wordCount
        }
    }

    /// What the outline tells a client about who it is to this work.
    public struct WorkAccess: Codable, Hashable, Sendable {
        /// The chapters they may change, when they were handed only some. Absent
        /// means the whole work. Reading is never narrowed.
        public var chapterIds: [String]?
        /// Whether they started the work — the one thing an added owner is not.
        public var creator: Bool
        /// Whose book it is.
        public var owner: AuthorCard
        public var role: CollaboratorRole

        public init(
            chapterIds: [String]? = nil,
            creator: Bool,
            owner: AuthorCard,
            role: CollaboratorRole
        ) {
            self.chapterIds = chapterIds
            self.creator = creator
            self.owner = owner
            self.role = role
        }
    }

    public struct WorkActivity: Codable, Hashable, Sendable {
        public var actorId: String
        public var createdAt: String
        public var id: String
        public var kind: ActivityKind
        /// The title as it was at the time.
        public var subject: String
        public var subjectId: String?
        /// How many acts this line stands for.
        public var times: Int
        public var updatedAt: String
        public var workId: String

        public init(
            actorId: String,
            createdAt: String,
            id: String,
            kind: ActivityKind,
            subject: String,
            subjectId: String? = nil,
            times: Int,
            updatedAt: String,
            workId: String
        ) {
            self.actorId = actorId
            self.createdAt = createdAt
            self.id = id
            self.kind = kind
            self.subject = subject
            self.subjectId = subjectId
            self.times = times
            self.updatedAt = updatedAt
            self.workId = workId
        }
    }

    public enum WorkKind: String, Codable, CaseIterable, Hashable, Sendable {
        case novel = "novel"
        case novella = "novella"
        case short_story = "short_story"
        case serial = "serial"
    }

    public struct WorkLink: Codable, Hashable, Sendable {
        public var id: String
        public var title: String

        public init(
            id: String,
            title: String
        ) {
            self.id = id
            self.title = title
        }
    }

    public enum WorkStatus: String, Codable, CaseIterable, Hashable, Sendable {
        case draft = "draft"
        case published = "published"
        case final = "final"
        case archived = "archived"
    }

    public struct WritingDay: Codable, Hashable, Sendable {
        public var createdAt: String
        /// The writer's local date, `YYYY-MM-DD`.
        public var day: String
        public var id: String
        public var netWords: Int
        public var saves: Int
        public var updatedAt: String
        public var userId: String

        public init(
            createdAt: String,
            day: String,
            id: String,
            netWords: Int,
            saves: Int,
            updatedAt: String,
            userId: String
        ) {
            self.createdAt = createdAt
            self.day = day
            self.id = id
            self.netWords = netWords
            self.saves = saves
            self.updatedAt = updatedAt
            self.userId = userId
        }
    }

    public struct WritingSummary: Codable, Hashable, Sendable {
        /// The writer's target, if they have set one.
        public var dailyWordGoal: Int?
        /// Most recent first, one entry per day the writer showed up.
        public var history: [WritingDay]
        public var savesToday: Int
        /// Consecutive days up to and including today on which they wrote.
        public var streak: Int
        public var today: String
        /// The Monday of the week `today` falls in. Weeks start on Monday, as the
        /// ISO calendar does.
        public var weekStart: String
        public var weeklyWordGoal: Int?
        /// Net words from `week_start` to `today`.
        public var wordsThisWeek: Int
        /// Net words on `today`, which may be negative on a day spent cutting.
        public var wordsToday: Int

        public init(
            dailyWordGoal: Int? = nil,
            history: [WritingDay],
            savesToday: Int,
            streak: Int,
            today: String,
            weekStart: String,
            weeklyWordGoal: Int? = nil,
            wordsThisWeek: Int,
            wordsToday: Int
        ) {
            self.dailyWordGoal = dailyWordGoal
            self.history = history
            self.savesToday = savesToday
            self.streak = streak
            self.today = today
            self.weekStart = weekStart
            self.weeklyWordGoal = weeklyWordGoal
            self.wordsThisWeek = wordsThisWeek
            self.wordsToday = wordsToday
        }
    }
}
